function aliasEmoji(text) {
  let out = String(text).replace(/\uFE0F/g, '');
  for (const from of Object.keys(ICON_ALIAS)) {
    if (out.indexOf(from) !== -1) out = out.split(from).join(ICON_ALIAS[from]);
  }
  return out;
}

