function __guessEmojiKey(text, data) {
  const hay = (String(text || '') + ' ' + String(data || '')).toLowerCase();
  for (const [re, emoji] of __ICON_HINTS) {
    if (re.test(hay)) return emoji;
  }
  return null;
}

const __PREMIUM_KEYS = Object.keys(PREMIUM_EMOJI_MAP).sort((a, b) => b.length - a.length);
const __PREMIUM_ESC = __PREMIUM_KEYS.map(k => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
const __PREMIUM_RE = new RegExp('(' + __PREMIUM_ESC.join('|') + ')\\uFE0F?', 'g');
const __ALIAS_KEYS = Object.keys(ICON_ALIAS);

function __looksEmoji(text) {
  if (!text) return false;
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    if (c >= 0x2190 && c <= 0x2BFF) return true;
    if (c >= 0x2600 && c <= 0x27BF) return true;
    if (c >= 0xD800 && c <= 0xDBFF) return true;
    if (c === 0xFE0F) return true;
  }
  for (const a of __ALIAS_KEYS) {
    if (text.indexOf(a) !== -1) return true;
  }
  return false;
}

/* Bọc emoji basic -> <tg-emoji>. Bỏ qua tag HTML, <code>, <pre>. */
function premiumify(text) {
  if (typeof text !== 'string' || !text) return text;
  if (!__looksEmoji(text)) return text;

  // cất các khối không được chạm vào
  const saved = [];
  let out = text.replace(
    /<tg-emoji\b[^>]*>[\s\S]*?<\/tg-emoji>|<code\b[^>]*>[\s\S]*?<\/code>|<pre\b[^>]*>[\s\S]*?<\/pre>/g,
    (m) => {
      saved.push(m);
      return '\u0000' + (saved.length - 1) + '\u0000';
    }
  );

  // đổi emoji basic -> premium (không đụng vào phần nằm trong thẻ HTML)
  const parts = out.split(/(<\/?[a-zA-Z][^>]*>)/g);
  for (let i = 0; i < parts.length; i++) {
    const chunk = parts[i];
    if (!chunk || chunk.charCodeAt(0) === 60) continue; // thẻ HTML
    if (!__looksEmoji(chunk)) continue;
    const aliased = aliasEmoji(chunk);
    parts[i] = aliased.replace(__PREMIUM_RE, (m, emoji) => {
      const key = emoji.replace(/\uFE0F/g, '');
      const id = PREMIUM_EMOJI_MAP[key] || PREMIUM_EMOJI_MAP[emoji];
      if (!id) return m;
      return '<tg-emoji emoji-id="' + id + '">' + emoji + '</tg-emoji>';
    });
  }
  out = parts.join('');

  return out.replace(/\u0000(\d+)\u0000/g, (m, i) => saved[Number(i)]);
}

/* Chỉ đụng vào text khi tin nhắn thực sự gửi ở parse_mode HTML */
function isHtmlMode(options) {
  return !!(options && typeof options === 'object' && String(options.parse_mode || '').toLowerCase() === 'html');
}

/* ---------- Nút bấm: tách emoji -> icon_custom_emoji_id ---------- */
function decorateButton(btn) {
  if (!btn || typeof btn !== "object" || typeof btn.text !== "string" || !btn.text) return btn;

  // 0) Nút chỉ có số (lịch chọn ngày 1..31) -> không gắn icon, giữ sạch
  if (/^\d{1,3}$/.test(btn.text.trim())) {
    const plainNum = Object.assign({}, btn);
    delete plainNum.icon_custom_emoji_id;
    return plainNum;
  }

  // 1) Luôn bóc sạch emoji khỏi chữ. Chữ + icon cùng lúc = icon bị nhân đôi (lỗi cũ).
  let mapped = null;
  let rest = btn.text;
  if (__looksEmoji(btn.text)) {
    rest = aliasEmoji(btn.text).replace(__PREMIUM_RE, (m, emoji) => {
      const key = emoji.replace(/\uFE0F/g, "");
      const id = PREMIUM_EMOJI_MAP[key] || PREMIUM_EMOJI_MAP[emoji];
      if (id && !mapped) mapped = String(id);
      return "";
    });
  }

  const clean = String(rest)
    // 1b) Emoji chua co trong bang premium -> bo han khoi chu (thon mat con hon hien emoji basic lech style)
    .replace(/[\u2190-\u2BFF\uFE0F]|[\u{1F000}-\u{1FAFF}]/gu, "")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/^[\s·•|\-–—◀▶]+/, "")
    .replace(/[\s·•|\-–—◀▶]+$/, "")
    .trim();
  // 1c) Nut chi co 1 emoji (vi du nut +/-) -> chu ASCII, icon premium giu nguyen nghia
  const SYMBOL_TEXT = { "➖": "-", "➕": "+", "✖": "x", "✔": "v", "⭐": "*" };
  const bareSym = String(btn.text).replace(/[\u2190-\u2BFF\uFE0F]|[\u{1F000}-\u{1FAFF}]/gu, "").trim();
  const out = Object.assign({}, btn);
  out.text = clean || SYMBOL_TEXT[String(btn.text).trim()] || String(btn.text).trim().slice(0, 2) || "Menu";

  // 2) Icon: icon tác giả gắn sẵn (đã xác minh) > emoji trong chữ > đoán theo nghĩa.
  let iconId = btn.icon_custom_emoji_id ? String(btn.icon_custom_emoji_id) : null;
  if (!iconId && !mapped) {
    const t0 = String(btn.text).trim().replace(/\uFE0F/g, "");
    if (PREMIUM_EMOJI_MAP[t0]) mapped = String(PREMIUM_EMOJI_MAP[t0]);
  }
  if (!iconId && mapped) iconId = mapped;
  if (!iconId && !__looksEmoji(out.text)) {
    const g = __guessEmojiKey(btn.text, btn.callback_data || btn.url);
    const gk = g ? g.replace(/\uFE0F/g, '') : null;
    const gid = gk ? (PREMIUM_EMOJI_MAP[gk] || null) : null;
    if (gid) iconId = String(gid);
  }
  if (iconId && BAD_ICON_IDS.has(iconId)) iconId = null;

  if (iconId) out.icon_custom_emoji_id = iconId;
  else delete out.icon_custom_emoji_id;
  return out;
}

function decorateKeyboard(rows) {
  if (!Array.isArray(rows)) return rows;
  return rows.map((row) => (Array.isArray(row) ? row.map(decorateButton) : decorateButton(row)));
}

function stripKeyboardIcons(rows) {
  if (!Array.isArray(rows)) return rows;
  const strip = (b) => {
    if (!b || typeof b !== 'object' || !b.icon_custom_emoji_id) return b;
    const copy = Object.assign({}, b);
    delete copy.icon_custom_emoji_id;
    return copy;
  };
  return rows.map((row) => (Array.isArray(row) ? row.map(strip) : strip(row)));
}

/* Gắn premium emoji vào MỌI lời gọi gửi/sửa tin nhắn của bot.
 * Một cửa duy nhất -> không phải sửa 5000 dòng template bên dưới. */
function installPremiumEmoji(bot) {
  const withKeyboard = (opts) => {
    if (!opts || typeof opts !== 'object') return opts;
    const rp = opts.reply_markup;
    if (!rp || !Array.isArray(rp.inline_keyboard)) return opts;
    return Object.assign({}, opts, {
      reply_markup: Object.assign({}, rp, { inline_keyboard: decorateKeyboard(rp.inline_keyboard) })
    });
  };
  const withPlainKeyboard = (opts) => {
    if (!opts || typeof opts !== 'object') return opts;
    const rp = opts.reply_markup;
    if (!rp || !Array.isArray(rp.inline_keyboard)) return opts;
    return Object.assign({}, opts, {
      reply_markup: Object.assign({}, rp, { inline_keyboard: stripKeyboardIcons(rp.inline_keyboard) })
    });
  };

  const transform = (name, args, mode) => {
    const a = args.slice();
    const premium = mode === 'premium';
    const kb = premium ? withKeyboard : withPlainKeyboard;

    if (name === 'sendMessage') {
      if (typeof a[1] === 'string' && isHtmlMode(a[2])) a[1] = premiumify(a[1]);
      if (a[2] && typeof a[2] === 'object') a[2] = kb(a[2]);
      return a;
    }
    if (name === 'editMessageText') {
      if (typeof a[0] === 'string' && isHtmlMode(a[1])) a[0] = premiumify(a[0]);
      if (a[1] && typeof a[1] === 'object') a[1] = kb(a[1]);
      return a;
    }
    if (name === 'editMessageCaption') {
      if (typeof a[0] === 'string' && isHtmlMode(a[1])) a[0] = premiumify(a[0]);
      if (a[1] && typeof a[1] === 'object') a[1] = kb(a[1]);
      return a;
    }
    if (name === 'editMessageReplyMarkup') {
      if (a[0] && typeof a[0] === 'object' && Array.isArray(a[0].inline_keyboard)) {
        const rows = premium ? decorateKeyboard(a[0].inline_keyboard) : stripKeyboardIcons(a[0].inline_keyboard);
        a[0] = Object.assign({}, a[0], { inline_keyboard: rows });
      }
      return a;
    }
    // sendPhoto / sendDocument / sendVideo / sendAnimation: (chatId, file, options, fileOptions)
    if (a[2] && typeof a[2] === 'object') {
      let opts = a[2];
      if (premium && typeof opts.caption === 'string' && isHtmlMode(opts)) {
        opts = Object.assign({}, opts, { caption: premiumify(opts.caption) });
      }
      a[2] = kb(opts);
    }
    return a;
  };

  const markBadIcons = (args) => {
    const scan = (opts) => {
      const rp = opts && opts.reply_markup;
      if (!rp || !Array.isArray(rp.inline_keyboard)) return;
      rp.inline_keyboard.forEach((row) => (row || []).forEach((b) => {
        if (b && b.icon_custom_emoji_id) BAD_ICON_IDS.add(String(b.icon_custom_emoji_id));
      }));
    };
    args.forEach((x) => {
      if (x && typeof x === 'object') scan(x);
    });
  };

  const wrap = (name) => {
    const orig = bot[name];
    if (typeof orig !== 'function') return;
    bot[name] = function (...args) {
      let decorated;
      try {
        decorated = transform(name, args, 'premium');
      } catch (err) {
        decorated = args;
      }
      return Promise.resolve(orig.apply(bot, decorated)).catch((err) => {
        const msg = String((err && err.message) || err);
        if (/BUTTON|CUSTOM_EMOJI|custom emoji|icon_custom_emoji/i.test(msg)) {
          try { markBadIcons(decorated); } catch (_) {}
          let plain;
          try { plain = transform(name, args, 'plain'); } catch (_) { plain = args; }
          return orig.apply(bot, plain);
        }
        throw err;
      });
    };
  };

  ['sendMessage', 'editMessageText', 'sendPhoto', 'sendDocument', 'sendVideo', 'sendAnimation', 'editMessageCaption', 'editMessageReplyMarkup'].forEach(wrap);

  bot.__premiumEmoji = { premiumify, decorateKeyboard, stripKeyboardIcons, PREMIUM_EMOJI_MAP, ICON_ALIAS, BAD_ICON_IDS };
  return bot;
}


