async function fetchRealWeather(city) {
  try {
    const res = await fetch(`https://wttr.in/${encodeURIComponent(city)}?format=j1`);
    const data = await res.json();
    const current = data.current_condition[0];
    return {
      location: city.toUpperCase(),
      temp: `${current.temp_C}°C (Cảm giác ${current.FeelsLikeC}°C)`,
      humidity: `${current.humidity}%`,
      condition: current.weatherDesc[0].value,
      wind: `${current.windspeedKmph} km/h`
    };
  } catch (e) {
    return {
      location: city.toUpperCase(),
      temp: '28°C - 32°C',
      humidity: '75%',
      condition: 'Trời quang mây tạnh',
      wind: '10 km/h'
    };
  }
}

function generateWelcomeCard(user) {
  const W = 900;
  const H = 500;
  const canvas = createCanvas(W, H);
  const ctx = canvas.getContext('2d');

  const rr = (x, y, w, h, r) => {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  };

  // ---- nền ----
  const bg = ctx.createLinearGradient(0, 0, W, H);
  bg.addColorStop(0, '#060912');
  bg.addColorStop(0.45, '#101538');
  bg.addColorStop(1, '#04060d');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // ---- quầng sáng ----
  const glow = (x, y, r, color) => {
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, color);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);
  };
  glow(W * 0.16, 70, 330, 'rgba(56,189,248,0.30)');
  glow(W * 0.88, H - 40, 360, 'rgba(168,85,247,0.26)');

  // ---- khung ----
  ctx.strokeStyle = 'rgba(56,189,248,0.45)';
  ctx.lineWidth = 2;
  rr(22, 22, W - 44, H - 44, 24);
  ctx.stroke();

  ctx.strokeStyle = 'rgba(255,255,255,0.06)';
  ctx.lineWidth = 1;
  rr(32, 32, W - 64, H - 64, 18);
  ctx.stroke();

  // ---- header ----
  ctx.textAlign = 'left';
  const titleGrad = ctx.createLinearGradient(46, 0, 380, 0);
  titleGrad.addColorStop(0, '#facc15');
  titleGrad.addColorStop(1, '#fbbf24');
  ctx.fillStyle = titleGrad;
  ctx.font = 'bold 25px sans-serif';
  ctx.fillText((config.SHOP_NAME || 'SYSTEM').toUpperCase(), 48, 74);

  ctx.fillStyle = 'rgba(148,163,184,0.85)';
  ctx.font = '13px monospace';
  ctx.fillText('DIGITAL ACCOUNT STORE', 48, 96);

  ctx.textAlign = 'right';
  ctx.fillStyle = '#38bdf8';
  ctx.font = 'bold 14px monospace';
  ctx.fillText('[ 24/7 AUTO DELIVERY ]', W - 48, 74);

  ctx.strokeStyle = 'rgba(56,189,248,0.28)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(48, 116);
  ctx.lineTo(W - 48, 116);
  ctx.stroke();

  // ---- lời chào ----
  ctx.textAlign = 'left';
  ctx.fillStyle = '#94a3b8';
  ctx.font = 'bold 16px sans-serif';
  ctx.fillText('X I N   C H À O', 48, 168);

  let uName = getFullName(user);
  if (uName.length > 22) uName = uName.substring(0, 21) + '...';
  const nameGrad = ctx.createLinearGradient(48, 0, W - 90, 0);
  nameGrad.addColorStop(0, '#4ade80');
  nameGrad.addColorStop(0.55, '#38bdf8');
  nameGrad.addColorStop(1, '#a855f7');
  ctx.fillStyle = nameGrad;
  ctx.font = 'bold 46px sans-serif';
  ctx.fillText(uName.toUpperCase(), 48, 226);

  ctx.fillStyle = '#64748b';
  ctx.font = '14px monospace';
  ctx.fillText('UID ' + maskUid(user.id) + '   •   TRẠNG THÁI: TRỰC TUYẾN', 48, 256);

  // ---- 3 khối thông tin ----
  const pills = [
    ['GIAO TỰ ĐỘNG', 'Nhận acc trong 5 giây'],
    ['BẢO HÀNH', 'Đổi trả theo chính sách'],
    ['HỖ TRỢ 24/7', 'Admin luôn trực chiến']
  ];
  const pw = (W - 96 - 2 * 16) / 3;
  pills.forEach((p, idx) => {
    const x = 48 + idx * (pw + 16);
    const y = 292;
    ctx.fillStyle = 'rgba(15,23,42,0.72)';
    rr(x, y, pw, 92, 14);
    ctx.fill();
    ctx.strokeStyle = idx === 0 ? 'rgba(74,222,128,0.35)' : (idx === 1 ? 'rgba(250,204,21,0.32)' : 'rgba(56,189,248,0.32)');
    ctx.lineWidth = 1;
    rr(x, y, pw, 92, 14);
    ctx.stroke();

    ctx.fillStyle = idx === 0 ? '#4ade80' : (idx === 1 ? '#facc15' : '#38bdf8');
    ctx.font = 'bold 15px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(p[0], x + pw / 2, y + 36);

    ctx.fillStyle = '#94a3b8';
    ctx.font = '12px sans-serif';
    ctx.fillText(p[1], x + pw / 2, y + 62);
    ctx.textAlign = 'left';
  });

  // ---- footer ----
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(148,163,184,0.75)';
  ctx.font = '13px monospace';
  ctx.fillText('BẤM NÚT BÊN DƯỚI ĐỂ MỞ CỬA HÀNG  •  ' + new Date().toLocaleDateString('vi-VN'), W / 2, 432);

  return canvas.toBuffer('image/png');
}

