/* ==================================================================
 * DOANH THU THEO NGÀY + LỊCH CHỌN NGÀY (múi giờ Việt Nam, UTC+7)
 * ================================================================== */
const VN_TZ_OFFSET_MS = 7 * 60 * 60 * 1000;
const pad2 = (n) => String(n).padStart(2, '0');

function vnNowParts() {
  const d = new Date(Date.now() + VN_TZ_OFFSET_MS);
  return { y: d.getUTCFullYear(), m: d.getUTCMonth() + 1, d: d.getUTCDate() };
}

function vnTodayStr() {
  const p = vnNowParts();
  return `${p.y}-${pad2(p.m)}-${pad2(p.d)}`;
}

function vnMonthStr() {
  const p = vnNowParts();
  return `${p.y}-${pad2(p.m)}`;
}

function isValidDayStr(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s || ''))) return false;
  const [y, m, d] = String(s).split('-').map(Number);
  if (y < 2020 || y > 2100 || m < 1 || m > 12 || d < 1) return false;
  const dim = new Date(Date.UTC(y, m, 0)).getUTCDate();
  return d <= dim;
}

function fmtDayVN(dayStr) {
  const parts = String(dayStr).split('-');
  return `${parts[2]}/${parts[1]}/${parts[0]}`;
}

function fmtMonthVN(monthStr) {
  const parts = String(monthStr).split('-');
  return `${parts[1]}/${parts[0]}`;
}

function shiftDay(dayStr, delta) {
  const [y, m, d] = String(dayStr).split('-').map(Number);
  const t = Date.UTC(y, m - 1, d) + delta * 24 * 60 * 60 * 1000;
  const nd = new Date(t);
  return `${nd.getUTCFullYear()}-${pad2(nd.getUTCMonth() + 1)}-${pad2(nd.getUTCDate())}`;
}

function shiftMonth(monthStr, delta) {
  const [y, m] = String(monthStr).split('-').map(Number);
  const total = y * 12 + (m - 1) + delta;
  const ny = Math.floor(total / 12);
  const nm = (total % 12 + 12) % 12 + 1;
  return `${ny}-${pad2(nm)}`;
}

/* Nhận 28/10/2026 · 28-10-2026 · 2026-10-28 · 28/10 (năm hiện tại) */
function parseDayInput(raw) {
  const t = String(raw || '').trim().replace(/[.\s]/g, '/').replace(/-/g, '/');
  let m = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) {
    const out = `${m[3]}-${pad2(m[2])}-${pad2(m[1])}`;
    return isValidDayStr(out) ? out : null;
  }
  m = t.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);
  if (m) {
    const out = `${m[1]}-${pad2(m[2])}-${pad2(m[3])}`;
    return isValidDayStr(out) ? out : null;
  }
  m = t.match(/^(\d{1,2})\/(\d{1,2})$/);
  if (m) {
    const out = `${vnNowParts().y}-${pad2(m[2])}-${pad2(m[1])}`;
    return isValidDayStr(out) ? out : null;
  }
  return null;
}

/* --- Báo cáo doanh thu của MỘT ngày bất kỳ (ảnh + nút chọn ngày) --- */
