/* ==================================================================
 * CAPTCHA CHO NGƯỜI DÙNG LẦN ĐẦU (toán cộng + 4 lựa chọn số)
 * ------------------------------------------------------------------
 * - Chỉ hỏi 1 lần / tài khoản (lưu cột verified trong bảng users).
 * - Admin không bao giờ bị hỏi. User cũ (tạo trước khi bật) cũng không.
 * - Câu hỏi sống 5 phút; nonce cũ bị từ chối -> không bấm lại được câu cũ.
 * - Mỗi lần bấm chỉ trả lời callback 1 lần (không quay vòng nút).
 * - DB lỗi -> fail-open (coi như đã xác minh), tuyệt đối không khoá user.
 * ================================================================== */
const CAPTCHA_TTL_MS = 5 * 60 * 1000;
const captchaState = new Map();

function __capNonce() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

/* Sinh câu hỏi mới cho user -> { nonce, text, keyboard } */
function __buildCaptchaView(userId) {
  const a = 1 + Math.floor(Math.random() * 9);
  const b = 1 + Math.floor(Math.random() * 9);
  const ans = a + b;

  const pool = new Set([ans]);
  while (pool.size < 4) {
    const delta = 1 + Math.floor(Math.random() * 5);
    const cand = Math.random() < 0.5 ? ans - delta : ans + delta;
    if (cand > 0 && cand !== ans) pool.add(cand);
  }
  const options = Array.from(pool);
  for (let i = options.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [options[i], options[j]] = [options[j], options[i]];
  }

  const nonce = __capNonce();
  captchaState.set(userId, { nonce, ans, at: Date.now() });

  const text =
`╭━━━━━━━━━━━━━━━━━━━━━━━━━━━━━╮
  🔒 <b>XÁC MINH NGƯỜI DÙNG MỚI</b>
╰━━━━━━━━━━━━━━━━━━━━━━━━━━━━━╯
 ├ 📝 <b>Phép tính:</b> <code>${a} + ${b} = ?</code>
 ├ 🎯 <b>Chọn đáp án đúng</b> bên dưới
 ╰ ⏳ <i>Câu hỏi hết hạn sau 5 phút</i>
─────────────────────────
<i>Chỉ hỏi một lần duy nhất để chống spam. Sau khi đúng, bạn vào shop luôn.</i>`;

  const keyboard = [
    options.slice(0, 2).map((num) => ({
      text: String(num),
      callback_data: `cap_opt_${nonce}_${num}`,
      style: 'primary'
    })),
    options.slice(2, 4).map((num) => ({
      text: String(num),
      callback_data: `cap_opt_${nonce}_${num}`,
      style: 'primary'
    })),
    [{ text: '🔄 Đổi câu hỏi khác', callback_data: `cap_new_${nonce}`, style: 'primary' }]
  ];

  return { nonce, text, keyboard };
}

async function sendCaptcha(bot, chatId, userId, messageId) {
  const view = __buildCaptchaView(userId);
  try {
    return await sendOrEditColoredMenu(bot, chatId, messageId, view.text, view.keyboard);
  } catch (e) {
    return bot.sendMessage(chatId, 'Vui lòng xác minh lại bằng lệnh /start.').catch(() => {});
  }
}

/* Có cần bắt xác minh không (lỗi DB -> coi như đã xác minh) */
async function needsCaptcha(userId) {
  if (isAdmin(userId)) return false;
  try {
    if (typeof db.isUserVerified !== 'function') return false;
    return !(await db.isUserVerified(userId));
  } catch (e) {
    return false;
  }
}

/* Trả về true nếu đã xử lý xong (đúng/sai/hết hạn) -> handler dừng lại */
async function handleCaptchaCallback(bot, chatId, userId, messageId, data, answer) {
  if (data.startsWith('cap_new_')) {
    const nonce = data.slice('cap_new_'.length);
    const state = captchaState.get(userId);
    if (!state || state.nonce !== nonce) {
      await answer({ text: 'Câu hỏi đã cũ, mình tạo câu mới nhé!' });
      await sendCaptcha(bot, chatId, userId, messageId);
      return true;
    }
    await answer({ text: 'Đã đổi câu hỏi khác!' });
    await sendCaptcha(bot, chatId, userId, messageId);
    return true;
  }

  if (data.startsWith('cap_opt_')) {
    const rest = data.slice('cap_opt_'.length);
    const split = rest.lastIndexOf('_');
    const nonce = split > 0 ? rest.slice(0, split) : '';
    const picked = parseInt(rest.slice(split + 1), 10);
    const state = captchaState.get(userId);

    if (!state || state.nonce !== nonce) {
      await answer({ text: 'Câu hỏi đã cũ, mình tạo câu mới nhé!' });
      await sendCaptcha(bot, chatId, userId, messageId);
      return true;
    }
    if (Date.now() - state.at > CAPTCHA_TTL_MS) {
      captchaState.delete(userId);
      await answer({ text: 'Câu hỏi đã hết hạn (5 phút). Mình đổi câu mới!' });
      await sendCaptcha(bot, chatId, userId, messageId);
      return true;
    }
    if (picked !== state.ans) {
      await answer({ text: 'Sai rồi! Thử phép tính khác nhé.' });
      await sendCaptcha(bot, chatId, userId, messageId);
      return true;
    }

    captchaState.delete(userId);
    try { await db.setUserVerified(userId); } catch (_) {}
    try { await bot.deleteMessage(chatId, messageId); } catch (_) {}
    await answer({ text: 'Xác minh thành công! Chào mừng bạn.' });

    try {
      const { text, keyboard } = await buildHomeMenu(userId);
      await sendOrEditColoredMenu(bot, chatId, null, text, keyboard);
    } catch (e) {
      await bot.sendMessage(chatId, 'Xác minh xong! Gõ /menu để vào shop.').catch(() => {});
    }
    return true;
  }

  return false;
}

